def seed_capability_evidence(db):
    skills={x.name:x for x in db.scalars(select(ModelSkill)).all()}
    for name in sorted({row[2] for row in EVIDENCE}):
        if name not in skills:skills[name]=ModelSkill(key=name.casefold().replace(" / ","_").replace("-","_").replace(" ","_"),name=name);db.add(skills[name])
    db.flush();existing={(x.provider,x.model_id,x.skill_id,x.evaluation_name,x.source_url) for x in db.scalars(select(ModelCapabilityEvidence)).all()}
    for provider,model,skill,benchmark,raw,maximum,source,date,independent in EVIDENCE:
        key=(provider,model,skills[skill].id,benchmark,SOURCES[source])
        if key not in existing:db.add(ModelCapabilityEvidence(provider=provider,model_id=model,skill_id=skills[skill].id,evaluation_name=benchmark,raw_score=raw,evaluation_max=maximum,benchmark_weight=.75 if "SWE-bench Verified" in benchmark else 1,source_type="INDEPENDENT_BENCHMARK" if independent else "PROVIDER_BENCHMARK",source_url=SOURCES[source],provider_reported=not independent,independent=independent,evaluation_date=datetime.fromisoformat(date).replace(tzinfo=timezone.utc),confidence="MEDIUM"))
